function swingAngle(){const s=1-Math.max(0,swing)/.45;if(swing<=0)return -.3;if(s<.25)return -.3-.8*Math.sin(s/.25*Math.PI/2);if(s<.6)return -1.1+1.8*(s-.25)/.35;return .7-1*((s-.6)/.4)}
