let netBuf=null;
function net(px,py,ang,sway,full){const ox=px-20,oy=py-90,W=140,H=170;if(netBuf===null){try{netBuf=document.createElement('canvas');netBuf.width=W/2;netBuf.height=H/2}catch{netBuf=false}}if(!netBuf)return netShape(ctx,px,py,ang,sway,full);const g=netBuf.getContext('2d');g.setTransform(1,0,0,1,0,0);g.clearRect(0,0,W/2,H/2);g.setTransform(.5,0,0,.5,-ox/2,-oy/2);netShape(g,px,py,ang,sway,full);ctx.imageSmoothingEnabled=false;ctx.drawImage(netBuf,ox,oy,W,H)}
